function broadcastPlayer(v){let game=state.games.find(g=>g.id===v.game_id),now=Date.now(),start=new Date(v.starts_at).getTime(),end=start+Number(v.duration_seconds)*1000,status=now<start?'UPCOMING':now<end?'LIVE':'REPLAY';return `<div class="panel panel-pad"><span class="tag">${status}</span><h2>${esc(t(game?.home_team_id)?.name||'Home')} vs ${esc(t(game?.away_team_id)?.name||'Away')}</h2><p class="micro">${esc(fmtTime(v.starts_at))} · ${esc(status==='LIVE'?'As-live broadcast — no seeking ahead':'Replay available after scheduled broadcast finishes')}</p>${status==='UPCOMING'?`<div class="notice">This video premieres automatically at the scheduled game time. Keep this page open or return at game time.</div>`:`<video id="vblPlayer" playsinline preload="metadata" style="width:100%;background:#050b14;border-radius:12px;max-height:68vh" ${status==='REPLAY'?'controls':''}></video><div class="action-row" style="margin-top:12px"><button class="btn" id="startVideo">${status==='LIVE'?'▶ Join live broadcast':'▶ Play replay'}</button>${status==='LIVE'?'<span class="tag">LIVE · SEEK DISABLED</span>':''}</div>`}${state.leagueAdmin?`<div class="action-row" style="margin-top:14px"><button class="btn secondary" data-upload-video="${esc(v.game_id)}">Replace video</button><button class="btn danger" data-remove-video="${esc(v.game_id)}">Remove broadcast</button></div>`:''}</div>`}
