let videoClock=null;
function wirePlayer(){if(videoClock){clearInterval(videoClock);videoClock=null}let v=broadcastFor(state.watchGame)||state.broadcasts[0];let player=$('vblPlayer'),btn=$('startVideo');if(!v||!player||!btn)return;const path=/^https:\/\//i.test(v.storage_path)?v.storage_path:client.storage.from('vbl-game-videos').getPublicUrl(v.storage_path).data.publicUrl;player.src=path;let start=new Date(v.starts_at).getTime(),end=start+v.duration_seconds*1000;const live=()=>Date.now()>=start&&Date.now()<end;const keepInSync=()=>{if(!live()){if(Date.now()>=end){player.controls=true;if(videoClock){clearInterval(videoClock);videoClock=null}}return}const pos=Math.max(0,Math.min(v.duration_seconds-0.1,(Date.now()-start)/1000));player.controls=false;if(Math.abs(player.currentTime-pos)>1.5){try{player.currentTime=pos}catch{}}};player.addEventListener('seeking',()=>{if(live())keepInSync()});btn.onclick=async()=>{keepInSync();try{await player.play();btn.textContent='▶ Playing'}catch(e){toast('Playback failed: '+e.message)}};keepInSync();if(live())videoClock=setInterval(keepInSync,1000)}
// Supabase TUS v1: browser File.slice() produces a Blob for each 6 MiB PATCH.
// Never import a Node-oriented TUS adapter into the browser.
async function uploadVideoChunks(file,path,onProgress){
 const {data:{session},error:sessionError}=await client.auth.getSession();
 if(sessionError||!session?.access_token)throw new Error('Session expired. Sign in again.');
 const projectUrl=config.supabaseUrl.replace(/\/$/,'');
 const storageUrl=projectUrl.replace(/^(https:\/\/)([^./]+)(\.supabase\.co)/,'$1$2.storage$3');
 const endpoint=storageUrl+'/storage/v1/upload/resumable';
 const authorization='Bearer '+session.access_token;
 const encode=str=>btoa(unescape(encodeURIComponent(String(str))));
 const metadata={bucketName:'vbl-game-videos',objectName:path,contentType:file.type||'video/mp4',cacheControl:'3600'};
 const metadataHeader=Object.entries(metadata).map(([k,v])=>k+' '+encode(v)).join(',');
 const commonHeaders={'Authorization':authorization,'apikey':config.supabaseAnonKey,'Tus-Resumable':'1.0.0'};
 const request=async(url,options)=>{
  let last;
  for(let attempt=0;attempt<5;attempt++){
   try{
    const response=await fetch(url,options);
    if(response.ok)return response;
    let detail=await response.text();
    const error=new Error('Supabase upload HTTP '+response.status+': '+detail.slice(0,450));
    if(![408,429,500,502,503,504].includes(response.status))throw error;
    last=error;
   }catch(e){last=e;if(e.message?.startsWith('Supabase upload HTTP')&&!/HTTP (408|429|500|502|503|504)/.test(e.message))throw e;}
   if(attempt<4)await new Promise(r=>setTimeout(r,[500,1500,3000,5000][attempt]));
  }
  throw last;
 };
 const created=await request(endpoint,{method:'POST',headers:{...commonHeaders,'Upload-Length':String(file.size),'Upload-Metadata':metadataHeader,'x-upsert':'false'}});
 const location=created.headers.get('Location');
 if(!location)throw new Error('Supabase did not return a TUS upload URL. Check Storage and CORS configuration.');
 const url=new URL(location,endpoint).href;
 const chunkSize=6*1024*1024;
 let offset=0;
 while(offset<file.size){
  // HEAD each chunk so retries after uncertain network outcomes never duplicate bytes.
  const head=await request(url,{method:'HEAD',headers:commonHeaders});
  const remoteOffset=Number(head.headers.get('Upload-Offset'));
  if(!Number.isSafeInteger(remoteOffset)||remoteOffset<0||remoteOffset>file.size)throw new Error('Supabase returned an invalid upload offset.');
  offset=remoteOffset;
  if(offset>=file.size)break;
  const chunk=file.slice(offset,Math.min(offset+chunkSize,file.size));
  const patched=await request(url,{method:'PATCH',headers:{...commonHeaders,'Upload-Offset':String(offset),'Content-Type':'application/offset+octet-stream'},body:chunk});
  const next=Number(patched.headers.get('Upload-Offset'));
  offset=Number.isSafeInteger(next)&&next>offset?next:offset+chunk.size;
  onProgress(offset,file.size);
 }
}

async function videoUploader(gameId){
 if(!client||!state.leagueAdmin)return toast('Only authorized league video admins can attach recordings.');
 const game=state.games.find(g=>g.id===gameId);if(!game)return;
 const previous=broadcastFor(gameId);
 modal(previous?'Replace game video':'Attach game video',`<form id="videoForm">
 <div class="notice">Choose a local MP4/WebM OR paste a direct HTTPS MP4/WebM video URL already hosted online. There is no duration limit in VBL. Supabase still enforces file-size limits for uploads.</div>
 <p><b>${esc(t(game.home_team_id)?.name)} vs ${esc(t(game.away_team_id)?.name)}</b></p>
 <label class="field">Upload video file (optional if using URL)<input class="input" name="video" type="file" accept="video/mp4,video/webm"></label>
 <label class="field">OR direct video URL (.mp4/.webm)<input class="input" name="videoUrl" type="url" placeholder="https://your-video-host.com/game.mp4"></label>
 <label class="field">Duration in minutes (used if video metadata isn't readable)<input class="input" name="minutes" type="number" min="0.01" step="any" placeholder="e.g. 90"></label>
 <label class="field">Broadcast start (local time)<input class="input" name="starts" type="datetime-local" value="${esc(game.date?game.date+'T'+(game.time||'18:00'):'')}" required></label>
 <p class="micro" id="uploadStatus">An existing video stays published until the new one is saved successfully.</p>
 <button class="btn" type="submit" id="submitVideo">Save / Replace Video</button></form>`);
 $('videoForm').onsubmit=async e=>{
  e.preventDefault();const fd=new FormData(e.target),file=fd.get('video'),urlInput=String(fd.get('videoUrl')||'').trim(),date=new Date(fd.get('starts'));
  const hasFile=file instanceof File&&file.size>0;
  if((!hasFile&&!urlInput)||(hasFile&&urlInput))return toast('Choose a file OR a direct video URL.');
  if(!Number.isFinite(date.getTime()))return toast('Choose a valid broadcast start time.');
  let path='';
  if(urlInput){try{const u=new URL(urlInput);if(u.protocol!=='https:')throw Error();path=u.href}catch{return toast('Use a valid HTTPS direct video link.')}}
  let duration=Number(fd.get('minutes'))*60;
  if(!(duration>0)&&hasFile){
   try{duration=await Promise.race([new Promise((resolve,reject)=>{const video=document.createElement('video'),blob=URL.createObjectURL(file);function finish(val){URL.revokeObjectURL(blob);video.removeAttribute('src');video.load();resolve(val)}video.onloadedmetadata=()=>finish(video.duration);video.onerror=()=>finish(0);video.preload='metadata';video.src=blob}),new Promise(resolve=>setTimeout(()=>resolve(0),5000))]);}catch{duration=0}
  }
  if(!(Number.isFinite(duration)&&duration>0))return toast('Enter the game duration in minutes.');
  $('submitVideo').disabled=true;
  const status=$('uploadStatus');
  if(hasFile){
   path=`${gameId}/${uid()}.${/\.webm$/i.test(file.name)?'webm':'mp4'}`;
   try{
    if(file.size>6*1024*1024){await uploadVideoChunks(file,path,(sent,total)=>{status.textContent='Uploading '+Math.round(sent/total*100)+'%';});}
    else{const out=await client.storage.from('vbl-game-videos').upload(path,file,{contentType:file.type||'video/mp4',upsert:false});if(out.error)throw out.error;}
   }catch(error){status.textContent='Upload failed: '+(error.message||String(error));$('submitVideo').disabled=false;return;}
  }
  const result=await client.from('game_broadcasts').upsert({game_id:gameId,storage_path:path,starts_at:date.toISOString(),duration_seconds:Math.ceil(duration)},{onConflict:'game_id'});
  if(result.error){if(hasFile)await client.storage.from('vbl-game-videos').remove([path]);status.textContent='Saving failed: '+result.error.message;$('submitVideo').disabled=false;return;}
  if(previous?.storage_path&&previous.storage_path!==path&&!/^https:\/\//i.test(previous.storage_path)){
   client.storage.from('vbl-game-videos').remove([previous.storage_path]).catch(e=>console.warn('Old video cleanup:',e));
  }
  close();await sync();state.watchGame=gameId;link('watch');toast('Video saved');
 };
}
async function removeBroadcast(gameId){if(!state.leagueAdmin||!confirm('Remove this broadcast?'))return;let v=broadcastFor(gameId);if(!v)return;let {error}=await client.from('game_broadcasts').delete().eq('game_id',gameId);if(error)return toast(error.message);if(!/^https:\/\//i.test(v.storage_path))await client.storage.from('vbl-game-videos').remove([v.storage_path]);state.watchGame=null;await sync();link('watch');toast('Broadcast removed')}

