function resultEditor(game){
 if(!game||!(canEdit(game.home_team_id)||canEdit(game.away_team_id)))return toast('Not authorized');
 const h=t(game.home_team_id),a=t(game.away_team_id);if(!h||!a)return toast('Missing team');
 const existing=Array.isArray(game.set_scores)?game.set_scores:[];
 const row=(i,v={})=>`<div class="score-set-row" data-set-row style="border:1px solid #dce2e9;border-radius:12px;padding:12px;margin:9px 0"><div class="action-row" style="justify-content:space-between;align-items:center"><b class="set-label">Set ${i+1}</b><button type="button" class="btn secondary" data-remove-set>Remove set</button></div><div class="form-grid"><label class="field">${esc(h.name)} points<input class="input" name="homePoints" type="number" step="any" value="${esc(v.home??'')}" placeholder="Any score"></label><label class="field">${esc(a.name)} points<input class="input" name="awayPoints" type="number" step="any" value="${esc(v.away??'')}" placeholder="Any score"></label></div></div>`;
 modal('Enter set scores — no limits',`<form id="resultForm"><div class="notice">Add as many or as few sets as you want. Enter any numbers, including equal scores. There is no target score, required win margin, or required number of sets.</div><div id="setRows">${(existing.length?existing:[{}]).map((v,i)=>row(i,v)).join('')}</div><button type="button" class="btn secondary" id="addSet">+ Add another set</button><label class="field" style="margin-top:14px">Match winner (used for standings)<select class="select" name="selectedWinner"><option value="auto">Automatic from sets (choose manually if tied)</option><option value="${h.id}" ${game.winner_id===h.id?'selected':''}>${esc(h.name)}</option><option value="${a.id}" ${game.winner_id===a.id?'selected':''}>${esc(a.name)}</option></select></label><p class="micro">A blank set is ignored. When both team scores are equal, neither team wins that set. You can choose the match winner manually, even with no scored sets.</p><div id="scoreError" role="alert" style="color:#b42318;font-weight:700;margin:9px 0"></div><button class="btn" type="submit">Save scores and update standings</button></form>`);
 const rows=$('setRows');const renumber=()=>rows.querySelectorAll('[data-set-row]').forEach((r,i)=>r.querySelector('.set-label').textContent='Set '+(i+1));
 $('addSet').onclick=()=>{rows.insertAdjacentHTML('beforeend',row(rows.querySelectorAll('[data-set-row]').length));renumber()};
 rows.onclick=e=>{if(e.target.closest('[data-remove-set]')){e.target.closest('[data-set-row]').remove();renumber()}};
 $('resultForm').onsubmit=async e=>{
  e.preventDefault();const f=new FormData(e.target),sets=[];let hs=0,as=0;
  const issue=msg=>{$('scoreError').textContent=msg};$('scoreError').textContent='';
  for(const r of rows.querySelectorAll('[data-set-row]')){
   const hv=r.querySelector('[name=homePoints]').value.trim(),av=r.querySelector('[name=awayPoints]').value.trim();
   if(hv===''&&av==='')continue;
   if(hv===''||av===''){issue('Enter both team scores for a set, or leave both blank.');return}
   const home=Number(hv),away=Number(av);
   if(!Number.isFinite(home)||!Number.isFinite(away)){issue('Enter numeric scores.');return}
   sets.push({home,away});if(home>away)hs++;else if(away>home)as++;
  }
  let winning=f.get('selectedWinner');
  if(winning==='auto'){if(hs===as){issue('Set wins are tied. Select the match winner to save the result.');return}winning=hs>as?h.id:a.id}
  const data={...game,status:'final',home_score:hs,away_score:as,winner_id:winning,set_scores:sets};
  if(client){const {error}=await client.from('games').update({status:'final',home_score:hs,away_score:as,winner_id:winning,set_scores:sets}).eq('id',game.id);if(error){issue('Save failed: '+error.message);return}const updated=await client.from('games').select('*').eq('id',game.id).single();if(updated.error||!updated.data){issue('Could not confirm saved result');return}state.games=state.games.map(g=>g.id===game.id?updated.data:g)}
  else{state.games=state.games.map(g=>g.id===game.id?data:g);save()}
  close();render();toast(t(winning).name+' wins. Standings updated.');
 };
}
function byeEditor(item){let tm=t(state.teamId);if(!tm||!canEdit(tm.id))return toast('Not authorized');modal(item?'Edit bye week':'Add bye week',`<form id="byeForm"><p class="micro">${esc(tm.name)} will not have an opponent or score for this bye. It will not affect the team record.</p><label class="field">Bye week starting date<input class="input" type="date" name="date" value="${esc(item?.date||'')}" required></label><label class="field">Notes (optional)<input class="input" name="note" maxlength="120" placeholder="e.g. Week 4 / Rest and recovery" value="${esc(item?.note||'')}"></label><button class="btn" type="submit">Save bye week</button></form>`);$('byeForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),data={id:item?.id||uid(),team_id:tm.id,date:String(f.get('date')),note:String(f.get('note')||'').trim()};if(client){let {error}=await client.from('byes').upsert(data);if(error)return toast('Save failed: '+error.message)}else{state.byes=[...state.byes.filter(x=>x.id!==data.id),data];save()}close();if(client)await sync();render();toast('Bye week saved')};}


const canEditEvents=()=>state.isDemoAdmin||state.roles.some(r=>r.team_id===null)||state.leagueAdmin;
const eventTypes=['Expansion Draft','Draft','World Cup','Tournament','Awards Ceremony','Other'];
function eventsPage(){
 const items=[...state.events].sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));
 return `<main class="container"><div class="section-head"><div><div class="tiny">Official VBL calendar</div><h2>League events</h2><p>Expansion drafts, player drafts, World Cups and other activities.</p></div>${canEditEvents()?'<button class="btn lime" id="addEventBtn">+ Schedule event</button>':''}</div>
 <div class="admin-list">${items.length?items.map(e=>`<article class="panel panel-pad" style="border-left:5px solid #c9f36a"><span class="tag">${esc(e.type)}</span><h3 style="font:900 23px Outfit;margin:12px 0 6px">${esc(e.title)}</h3><p class="micro">${new Date(e.starts_at).toLocaleString('en-US',{dateStyle:'full',timeStyle:'short'})}${e.ends_at?' — '+new Date(e.ends_at).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short'}):''}</p>${e.location?`<p><b>Location:</b> ${esc(e.location)}</p>`:''}${e.description?`<p>${esc(e.description)}</p>`:''}${canEditEvents()?`<div class="action-row"><button class="btn secondary" data-event-edit="${esc(e.id)}">Edit</button><button class="btn danger" data-event-delete="${esc(e.id)}">Delete</button></div>`:''}</article>`).join(''):'<div class="empty panel">No events scheduled yet.</div>'}</div></main>`;
}
function eventEditor(item){
 if(!canEditEvents())return toast('Commissioner access required.');
 const localDate=d=>d?new Date(d).toLocaleString('sv-SE',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).replace(' ','T'):'';
 modal(item?'Edit league event':'Schedule league event',`<form id="eventForm"><label class="field">Event title<input class="input" name="title" maxlength="120" value="${esc(item?.title||'')}" required></label><label class="field">Event type<select class="select" name="type">${eventTypes.map(x=>`<option ${item?.type===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="form-grid"><label class="field">Starts<input class="input" name="starts_at" type="datetime-local" required value="${esc(localDate(item?.starts_at))}"></label><label class="field">Ends (optional)<input class="input" name="ends_at" type="datetime-local" value="${esc(localDate(item?.ends_at))}"></label></div><label class="field">Location or stream link<input class="input" name="location" maxlength="220" value="${esc(item?.location||'')}"></label><label class="field">Event details<textarea class="input" name="description" maxlength="1500" rows="4">${esc(item?.description||'')}</textarea></label><div id="eventError" class="micro" role="alert"></div><button class="btn lime" type="submit">Save event</button></form>`);
 $('eventForm').onsubmit=async evt=>{evt.preventDefault();const f=new FormData(evt.currentTarget);const start=new Date(String(f.get('starts_at'))),end=f.get('ends_at')?new Date(String(f.get('ends_at'))):null;if(isNaN(start)||end&&(+end<+start))return $('eventError').textContent='Enter valid dates; end must be after start.';const row={id:item?.id||uid(),title:String(f.get('title')).trim(),type:String(f.get('type')),starts_at:start.toISOString(),ends_at:end?.toISOString()||null,location:String(f.get('location')||'').trim(),description:String(f.get('description')||'').trim()};if(client){const {error}=await client.from('league_events').upsert(row);if(error)return $('eventError').textContent='Save failed: '+error.message;close();await sync();}else{state.events=[...state.events.filter(e=>e.id!==row.id),row];save();close();render();}toast('League event saved.');};
}
async function deleteEvent(id){if(!canEditEvents()||!confirm('Delete this event?'))return;if(client){const {error}=await client.from('league_events').delete().eq('id',id);if(error)return toast('Delete failed: '+error.message);await sync();}else{state.events=state.events.filter(e=>e.id!==id);save();render();}toast('Event deleted.');}


const newsKinds=['Trade','Signing','Release','Game Update','Injury Update','League Announcement','Other'];
function newsPage(){
 const items=[...state.news].sort((a,b)=>new Date(b.published_at)-new Date(a.published_at));
 return `<main class="container"><div class="section-head"><div><div class="tiny">VBL latest</div><h2>News & Transactions</h2><p>Trades, roster moves, game updates, and commissioner announcements.</p></div>${canEditEvents()?'<button id="addNewsBtn" class="btn lime">+ Publish update</button>':''}</div><div class="admin-list">${items.length?items.map(n=>`<article class="panel panel-pad" style="border-left:5px solid ${n.category==='Trade'?'#e5ad52':n.category==='Game Update'?'#57afdc':'#c9f36a'}"><div class="toolbar"><div><span class="tag">${esc(n.category)}</span><h3 style="font:900 23px Outfit;margin:12px 0 6px">${esc(n.title)}</h3><p class="micro">${new Date(n.published_at).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short'})}${n.team_id&&t(n.team_id)?' · '+esc(t(n.team_id).name):''}</p></div></div><p style="line-height:1.7;white-space:pre-wrap">${esc(n.body)}</p>${canEditEvents()?`<div class="action-row"><button class="btn secondary" data-news-edit="${esc(n.id)}">Edit</button><button class="btn danger" data-news-delete="${esc(n.id)}">Delete</button></div>`:''}</article>`).join(''):'<div class="empty panel">No news or transactions posted yet.</div>'}</div></main>`;
}
function newsEditor(n){
 if(!canEditEvents())return toast('Commissioner access required.');
 modal(n?'Edit update':'Publish update',`<form id="newsForm"><label class="field">Category<select class="select" name="category">${newsKinds.map(k=>`<option ${n?.category===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">Headline<input class="input" name="title" maxlength="180" required value="${esc(n?.title||'')}" placeholder="Trade: ..."></label><label class="field">Team (optional)<select class="select" name="team_id"><option value="">League-wide</option>${teams.map(x=>`<option value="${x.id}" ${n?.team_id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">Details<textarea class="input" name="body" rows="6" maxlength="10000" required>${esc(n?.body||'')}</textarea></label><p id="newsError" class="micro" role="alert"></p><button type="submit" class="btn lime">Publish update</button></form>`);
 $('newsForm').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.currentTarget);const row={id:n?.id||uid(),category:String(data.get('category')),title:String(data.get('title')).trim(),body:String(data.get('body')).trim(),team_id:data.get('team_id')||null,published_at:n?.published_at||new Date().toISOString()};if(!row.title||!row.body)return $('newsError').textContent='Headline and details are required.';if(client){const {error}=await client.from('league_news').upsert(row);if(error)return $('newsError').textContent='Save failed: '+error.message;close();await sync();}else{state.news=[...state.news.filter(x=>x.id!==row.id),row];save();close();render();}toast('Update published.');};
}
async function deleteNews(id){if(!canEditEvents()||!confirm('Delete this news update?'))return;if(client){let {error}=await client.from('league_news').delete().eq('id',id);if(error)return toast('Delete failed: '+error.message);await sync();}else{state.news=state.news.filter(x=>x.id!==id);save();render();}toast('Update deleted.');}

function authPage(){return `<main class="container" style="max-width:560px"><div class="section-head"><div><div class="tiny">VBL ACCOUNT ACCESS</div><h2>Sign in or create an account</h2><p>Watching games, viewing team pages, and checking standings never require signing in.</p></div></div><div class="panel panel-pad"><div class="action-row" style="margin-bottom:20px"><button class="btn" id="authModeSignIn">Sign in</button><button class="btn secondary" id="authModeSignUp">Create account</button></div><form id="authPageForm"><h2 id="authModeTitle" style="margin:0 0 18px">Sign in</h2><label class="field">Email address<input type="email" name="email" class="input" autocomplete="email" required></label><label class="field">Password<input type="password" name="password" class="input" autocomplete="current-password" minlength="6" required></label><p id="authPageFeedback" role="status" aria-live="polite" class="micro"></p><button class="btn" id="authSubmit" type="submit">Sign in</button></form><p class="micro" style="margin-top:18px">Only approved team managers can edit rosters and schedules. Only a commissioner assigned in Supabase can manage every team and upload games.</p><div id="authRecovery" style="margin-top:14px"><button class="btn ghost" id="resetPassword">Send password reset email</button></div>${!configured?'<div class="notice error" style="margin-top:18px">Supabase is not configured. Connect config.js for accounts. <button type="button" class="btn secondary" id="demoLogin">Open local demo editor</button></div>':''}<div style="margin-top:20px"><a href="#/home">← Continue as guest</a></div></div></main>`}
function wireAuthPage(){const form=$('authPageForm');if(!form)return;let mode='signin';const feedback=$('authPageFeedback');function setMode(next){mode=next;$('authModeTitle').textContent=mode==='signin'?'Sign in':'Create account';$('authSubmit').textContent=mode==='signin'?'Sign in':'Create account';form.elements.password.autocomplete=mode==='signin'?'current-password':'new-password';$('authRecovery').style.display=mode==='signin'?'block':'none';feedback.textContent='';} $('demoLogin')?.addEventListener('click',()=>{state.isDemoAdmin=true;link('admin')});$('authModeSignIn').onclick=()=>setMode('signin');$('authModeSignUp').onclick=()=>setMode('signup');$('resetPassword').onclick=async()=>{if(!client)return feedback.textContent='Configure Supabase first.';let email=form.elements.email.value.trim();if(!email)return feedback.textContent='Enter your email address first.';let {error}=await client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname+'#/auth'});feedback.textContent=error?error.message:'If this email is registered, a reset link will arrive shortly.'};form.onsubmit=async e=>{e.preventDefault();if(!client)return feedback.textContent='Configure Supabase first.';let email=form.elements.email.value.trim(), password=form.elements.password.value;const button=$('authSubmit');button.disabled=true;feedback.textContent='Connecting securely…';try{let result=mode==='signin'?await client.auth.signInWithPassword({email,password}):await client.auth.signUp({email,password,emailRedirectTo:location.origin+location.pathname+'#/auth'});if(result.error){feedback.textContent=result.error.message;return}if(mode==='signup'&&!result.data.session){feedback.textContent='Account created. Check your email for a confirmation link before signing in.';setMode('signin');feedback.textContent='Account created. Check your email for a confirmation link before signing in.';return}await sync();link('admin')}catch(err){feedback.textContent=err.message||'Unable to connect to Supabase.'}finally{button.disabled=false}}}
function login(){link('auth')}

async function remove(table,id){let item=state[table].find(x=>x.id===id);if(!item)return;let allowed=(table==='players'||table==='byes')?canEdit(item.team_id):canEdit(item.home_team_id)||canEdit(item.away_team_id);if(!allowed)return;if(!confirm('Remove this entry?'))return;if(client){let {error}=await client.from(table).delete().eq('id',id);if(error)return toast(error.message)}else{state[table]=state[table].filter(x=>x.id!==id);save()}if(client)await sync();render();toast('Removed')}
async function sync(){if(!client)return;let {data:{session}}=await client.auth.getSession();state.session=session;let [pr,gr,br,vr,ar,er,nr]=await Promise.all([client.from('players').select('*'),client.from('games').select('*'),client.from('byes').select('*'),client.from('game_broadcasts').select('*'),session?client.from('league_video_admins').select('user_id').eq('user_id',session.user.id):Promise.resolve({data:[]}),client.from('league_events').select('*').order('starts_at',{ascending:true}),client.from('league_news').select('*').order('published_at',{ascending:false})]);if(pr.error||gr.error||br.error){toast('Data error: '+(pr.error?.message||gr.error?.message||br.error?.message));return}state.players=pr.data||[];state.games=gr.data||[];state.byes=br.data||[];state.broadcasts=vr.data||[];state.events=er.error?[]:(er.data||[]);state.news=nr.error?[]:(nr.data||[]);if(nr.error)console.warn('Run VBL News SQL upgrade:',nr.error.message);if(er.error)console.warn('Run League Events SQL upgrade:',er.error.message);state.leagueAdmin=!!(session&&ar.data?.length);if(vr.error)console.warn('Broadcast setup needed:',vr.error.message);let rr=session?await client.from('team_managers').select('team_id').eq('user_id',session.user.id):{data:[]};state.roles=rr.data||[];render()}
const style=document.createElement('style');style.textContent=`.team-hero{color:white;padding:32px 28px 50px;position:relative;overflow:hidden}.team-hero:after{content:'VBL';position:absolute;right:-60px;bottom:-140px;font:900 360px Outfit;color:#ffffff09;pointer-events:none}.team-hero-content{z-index:1}.team-hero-main{display:flex;align-items:center;gap:48px;margin-top:16px}.team-hero-main img{width:225px;height:225px;object-fit:contain;filter:drop-shadow(0 18px 24px #0005)}.team-hero-main h1{font:900 clamp(35px,5vw,63px)/1.04 Outfit;margin:14px 0;letter-spacing:-2px}.team-hero-main p{color:#d4dde6}.hero-tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:24px}.hero-tags span{background:#ffffff19;border:1px solid #ffffff25;border-radius:30px;padding:9px 14px;font-size:11px;font-weight:900;letter-spacing:.5px}.bye-row{background:linear-gradient(90deg,#effaf8,#fff)}.bye-row .game-title{color:#116c65}.team-view .tab.selected{border-color:var(--teamaccent)}@media(max-width:610px){.team-hero{padding:26px 17px 35px}.team-hero-main{gap:14px;align-items:center}.team-hero-main img{width:112px;height:140px}.team-hero-main h1{font-size:30px;letter-spacing:-.8px}.hero-tags{margin-top:10px}.hero-tags span{padding:7px;font-size:9px}}`;document.head.append(style);
window.addEventListener('hashchange',goHash);if(client){client.auth.onAuthStateChange(()=>{setTimeout(sync,0)});sync().then(goHash)}else goHash();

const playoffStyle=document.createElement('style');playoffStyle.textContent=`.rank-team{display:flex;align-items:center;gap:10px;min-width:170px}.standings-scroll{overflow-x:auto}.standings-scroll .table{min-width:740px}.playoff-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:15px}.playoff-grid h3{font:800 16px Outfit}.series-card{border:1px solid var(--border);border-top:4px solid #96b6d3;border-radius:13px;background:#fff;margin-bottom:13px;padding:16px;display:grid;gap:10px}.series-team{display:flex;align-items:center;gap:9px;font-size:13px}.series-team>span:nth-child(2){flex:1;font-weight:800}.series-team>b{font:900 23px Outfit}.series-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px;flex-wrap:wrap}.series-foot button{font-size:11px}.series-game-list{display:grid;gap:5px}.series-game{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 9px;background:#f2f4f8;border-radius:8px;font-size:12px}.series-game span{display:grid;gap:3px}.series-game small{font-size:11px;color:#536078}.series-game .btn{padding:6px 9px;font-size:11px}.seed-strip{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;margin-bottom:12px}.seed{background:#f2f3f6;border:1px solid #e1e5ea;border-radius:10px;padding:12px 7px;display:grid;justify-items:center;gap:5px;text-align:center;font-size:10px}.seed.qualified{background:#eaf7e6;border-color:#c9e5bb}.seed>b{font-size:11px}.seed>span{font-weight:900}.seed small{color:#68758b}.placeholder-icon{border-radius:8px;background:#eee;padding:12px}@media(max-width:900px){.playoff-grid{grid-template-columns:1fr 1fr}.seed-strip{grid-template-columns:repeat(4,1fr)}}@media(max-width:580px){.playoff-grid{grid-template-columns:1fr}.seed-strip{grid-template-columns:repeat(2,1fr)}.links{flex-wrap:wrap;justify-content:flex-start;gap:10px 18px}}`;document.head.append(playoffStyle);
